INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('f409f927-b633-442a-aa45-9156292dcbad', 'kanji', '心', '心', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Hati radikal dan hati kanji adalah sama. Bergembiralah dan biarkan hatimu bebas!', 'Jantung, di mana disimpannya di tubuhmu? Kebanyakan orang mengira itu ada di dada, tapi kenyataannya, jantungmu tersimpan di tulang kering (しん).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
