INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('43918d15-2ac3-4a22-ba0d-1d6ac7801352', 'kanji', '少', '少', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Anda memiliki slide kecil. Hal yang menarik tentang perosotan kecil adalah bahwa perosotan tersebut hanya dapat memuat beberapa orang dalam satu waktu.', 'Mengapa ada sedikit kemacetan di perosotan? Karena Shougun (しょう) menggunakan slide dan dia menyukai hal-hal kecil. Dia memaksa semua orang untuk berhenti dan menonton, meskipun ada orang yang mendukungnya di belakangnya. Betapa tidak pengertiannya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
