INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('07ac5eeb-f625-4af3-817c-b3b4e954715f', 'kanji', '切', '切', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Jika Anda memiliki tujuh pedang, tidak banyak yang dapat Anda lakukan dengannya. Hal utama? Mungkin menggunakannya untuk memotong sesuatu.', 'Karena memiliki tujuh pedang untuk dirimu sendiri terlalu banyak, kamu memutuskan untuk mengambil pedang itu dan membaginya di antara beberapa orang. Anda memotongnya menjadi berpasangan, dan memberikan set (せつ) kepada semua orang yang membutuhkannya di desa.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
