INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('6ed84f05-23b5-4611-80e7-3b4becb50e7b', 'kanji', '止', '止', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Stop radikal sama dengan stop kanji.', 'Anda harus berhenti karena ada domba (し) di depan Anda. Anda mencoba berjalan mengitari domba tersebut, tetapi domba itu bergerak berhenti di depan Anda lagi. Setiap kali domba berhenti, Anda juga berhenti.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
