INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('fa07190b-fc75-4b59-bfb5-88c72ff21de5', 'kanji', '公', '公', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Anda memiliki sirip secara pribadi. Namun, Anda ingin dunia melihatnya, jadi publikasikanlah.', 'Anda pergi ke tempat umum di mana semua orang dapat melihat sirip Anda, tapi... segalanya telah berubah. Semua orang sama. Ada ribuan orang yang berjalan-jalan, dan mereka semua menatap Anda (meskipun mereka berpura-pura tidak melakukannya).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
