INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('0ab21533-8d9d-474c-9269-c80ecc0cfdb3', 'kanji', '犬', '犬', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kanji anjing radikal dan kanji anjing sama persis!', 'Anda melihat seekor emu berlari ke arah Anda dari kejauhan (aneh melihat seekor emu di bagian ini...). Ketika semakin dekat, Anda menyadari bahwa itu bukan emu sama sekali, itu adalah sesuatu yang terdengar sama, atau mirip... sebuah inu!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
