INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e66cacc3-8efa-42b4-b5a2-bbc5903fd1be', 'うし', 'kunyomi', false) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('7dc6c977-26cc-4055-b60f-d4e881a9eb7e', 'kanji', '目', '目', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Radikal mata dan kanji mata sama satu sama lain, jadi sekarang Anda sudah mengenal keduanya.', 'Mata Anda penting bagi Anda, bukan? Sedihnya, salah satu matamu hilang saat ini, karena seekor domba menyambar dan mencabutnya, dan kini melarikan diri darimu sambil meneriakkan panggilan dombanya.... "Mehhhhh (め)!"') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
