INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('612b440d-aefe-4a90-89d3-9556dc1e1862', 'kanji', '立', '立', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Stand radikal dan stand kanji adalah hal yang sama, jadi sekarang Anda sudah mengetahui keduanya.', 'Pikirkan seseorang yang harus berdiri tegak demi Anda. Orang-orang ini ahli dalam bidang perhotelan. Ini adalah penjaga pintu di Ritz (りつ).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
