INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('055ac98c-0e93-4444-87f6-f8b4bc9fa77b', 'kanji', '用', '用', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kanji dan radikalnya sama, jadi mengingat arti kanji ini semudah memastikan Anda mengetahui radikal untuk tugas terlebih dahulu! Jika Anda tahu radikalnya, Anda pasti tahu kanji ini juga berarti tugas.', 'Hari ini, tugasmu adalah makan yogurt (よう). Ini bergizi, enak, dan saya menyuruh Anda melakukannya, jadi Anda harus melakukannya. Tugas pada dasarnya hanyalah sesuatu yang harus Anda lakukan, jadi begitulah maksudnya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
