INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('97e7872e-69a7-4710-9c41-64c0458cac43', 'kanji', '仕', '仕', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Samurai pemimpin tidak menjadi pemimpin hanya dengan duduk diam dan tidak mengambil tindakan. Dia mencapai tempatnya sekarang dengan melakukan.', 'Dia melakukan sesuatu dengan domba (し). Dia adalah pemimpin klan domba, dan dia mampu berbuat lebih banyak dengan domba dibandingkan orang lain. Itu sebabnya dia adalah pemimpinnya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
