INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('73625a8a-ec89-4ce3-b6b2-2093638116bc', 'kanji', '可', '可', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Dengan cincin bibir, segala sesuatu mungkin terjadi. Memiliki cincin bibir memberi Anda kekuatan untuk menaklukkan rintangan apa pun, mencapai tujuan apa pun. Selama itu adalah cincin bibir yang lumayan. Kalau kurang bagus, tidak mungkin bisa lumayan.', 'Karena segala sesuatu mungkin terjadi dengan cincin bibir baru Anda yang lumayan, Anda menggunakannya untuk mendapatkan mobil baru (か). Anda pergi ke dealer mobil dan meminta mobil gratis (lumayan). Manajer terkesan dengan cincin bibir Anda dan dengan senang hati menyerahkan kunci model terbaru mobil favorit Anda. Tidak buruk.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
