INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d7bcd275-0788-4950-af8c-3db303f45de8', 'おなかがすいて、力がでない。', 'Saya lapar dan kehilangan kekuatan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d7bcd275-0788-4950-af8c-3db303f45de8', 'あのアメリカ人の女にはふじ山をうごかす力がある。', 'Wanita Amerika itu punya kekuatan untuk memindahkan Gunung Fuji.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d7bcd275-0788-4950-af8c-3db303f45de8', 'おかあさんは、のこりのかぞくがたばになってもかなわない力をもっている。', 'Ibuku lebih berkuasa dibandingkan anggota keluargaku yang lain.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6eb9541f-cfdb-457e-8a08-40bc9d4032e8', 'vocabulary', '口', '口', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Ketika sebuah kosakata terdiri dari satu kanji tanpa okurigana (hiragana yang melekat pada kanji), secara umum maknanya akan sama dengan kanji asalnya. Dari situ kamu tahu arti kata ini adalah mulut.', 'Ketika sebuah kosakata terdiri dari satu kanji tanpa okurigana (hiragana yang melekat pada kanji), secara umum maknanya akan sama dengan kanji asalnya. Dari situ kamu tahu arti kata ini adalah mulut.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6eb9541f-cfdb-457e-8a08-40bc9d4032e8', 'Mulut', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6eb9541f-cfdb-457e-8a08-40bc9d4032e8', 'くち', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6eb9541f-cfdb-457e-8a08-40bc9d4032e8', '口にソースがついていますよ。', 'Ada saus di mulutmu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6eb9541f-cfdb-457e-8a08-40bc9d4032e8', 'これを口に入れてください。', 'Tolong masukkan ini ke dalam mulutmu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6eb9541f-cfdb-457e-8a08-40bc9d4032e8', 'きのうから口がとじられない。', 'Saya belum bisa menutup mulut sejak kemarin.') ON CONFLICT DO NOTHING;
