INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f71a1465-b502-4e67-8fd9-cea3d347433d', '入り口のところでまっています。', 'Aku akan menunggumu di pintu masuk.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f71a1465-b502-4e67-8fd9-cea3d347433d', '入り口が三つあります。', 'Ada tiga pintu masuk.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f71a1465-b502-4e67-8fd9-cea3d347433d', '入り口にジョニーデップがいるよ。', 'Johnny Depp ada di pintu masuk.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7ee772b1-383d-4b2f-a9f2-904be213eac5', 'vocabulary', '夕べ', '夕べ', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kata vocab ini memiliki sedikit tambahan yang aneh (べ). Anda bisa mengabaikannya, itu tidak berarti apa pun secara khusus. Arti kosakata ini dan kanji asalnya sama: sore', 'Kata vocab ini memiliki sedikit tambahan yang aneh (べ). Anda bisa mengabaikannya, itu tidak berarti apa pun secara khusus. Arti kosakata ini dan kanji asalnya sama: sore') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
