INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4aef0f92-1adf-4b68-9a7d-147187046908', '手がカサカサになってしまいました。', 'Tanganku menjadi sangat kering.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4aef0f92-1adf-4b68-9a7d-147187046908', '手をつないでもいい？', 'Bolehkah aku memegang tanganmu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4aef0f92-1adf-4b68-9a7d-147187046908', 'パパの手はモジャモジャだ。', 'Lengan Ayah berbulu lebat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8f985df2-785c-4d26-856f-9c0ce8e9c362', 'vocabulary', '下手', '下手', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Bayangkan seseorang mengulurkan tangannya setinggi bahu. Apa pun di atas itu berarti “terampil”. Segala sesuatu di bawah itu sama dengan "tidak terampil". Jadi, dalam kasus kata ini, "di bawah tangan" berarti "tidak terampil."', 'Bayangkan seseorang mengulurkan tangannya setinggi bahu. Apa pun di atas itu berarti “terampil”. Segala sesuatu di bawah itu sama dengan "tidak terampil". Jadi, dalam kasus kata ini, "di bawah tangan" berarti "tidak terampil."') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
