INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('047fd314-c5a2-4ca6-9065-1df50b36a58a', '犬とねこがいます。', 'Ada seekor anjing dan seekor kucing.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('047fd314-c5a2-4ca6-9065-1df50b36a58a', 'その王は犬を六ぴきかっています。', 'Raja itu memiliki enam anjing.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('047fd314-c5a2-4ca6-9065-1df50b36a58a', 'わたしの犬は、白さいがすきだ。', 'Anjing saya suka kubis Cina.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7a57f3cd-55a2-444e-a4c9-55a6287b327f', 'vocabulary', '子犬', '子犬', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Seekor anak anjing adalah anak anjing!', 'Seekor anak anjing adalah anak anjing!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
