INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7a57f3cd-55a2-444e-a4c9-55a6287b327f', 'こいぬ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7a57f3cd-55a2-444e-a4c9-55a6287b327f', 'けさ、子犬がうまれました。', 'Anak-anak anjing itu lahir pagi ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7a57f3cd-55a2-444e-a4c9-55a6287b327f', 'その子犬は王子にもらった九つの玉をくびから下げて入り口に立っていた。', 'Anak anjing yang berdiri di pintu masuk diberi sembilan bola di lehernya oleh sang pangeran.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7a57f3cd-55a2-444e-a4c9-55a6287b327f', '子犬ごっこをしましょうよ。', 'Anggap saja kita anak anjing!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c58f9d31-5e27-41db-91e6-bd8e70380f73', 'vocabulary', '出口', '出口', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Mulut tempat Anda keluar hanyalah sebuah pintu keluar (saya harap), tetapi cara yang lebih mudah untuk menggambarkan kata atau konsep ini adalah dengan menyebutnya sebagai pintu keluar.', 'Mulut tempat Anda keluar hanyalah sebuah pintu keluar (saya harap), tetapi cara yang lebih mudah untuk menggambarkan kata atau konsep ini adalah dengan menyebutnya sebagai pintu keluar.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
