INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1730b1c0-a124-461a-9813-a4cf438c1cbe', '山下さんは、右手にくろいかさをもっています。', 'Nona Yamashita memegang payung hitam di tangan kanannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1730b1c0-a124-461a-9813-a4cf438c1cbe', '小さい女の子が、右手にビー玉をにぎりしめて立っていた。', 'Ada seorang gadis kecil yang memegang kelereng di tangan kanannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1730b1c0-a124-461a-9813-a4cf438c1cbe', 'あ、赤ちゃんの右手のひじにホクロがある！', 'Oh, bayi itu mempunyai tahi lalat di siku lengan kanannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1730b1c0-a124-461a-9813-a4cf438c1cbe', '右手の山はふじ山です。', 'Gunung di sisi kanan adalah Gunung Fuji.') ON CONFLICT DO NOTHING;
