INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d61f1cbd-c8ed-4247-97fe-744051d510c0', 'かれは、じぶんがいつも正しいとおもっている。', 'Dia selalu berpikir dia benar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d61f1cbd-c8ed-4247-97fe-744051d510c0', '王女はいつも正しくて、王子はいつもまちがっている。', 'Sang putri selalu benar dan sang pangeran selalu salah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d61f1cbd-c8ed-4247-97fe-744051d510c0', 'ぼくのこころのとびらをあけるには、正しいかぎがひつようだよ、ベイビー。', 'Jika kamu ingin membuka pintu hatiku, kamu memerlukan kunci yang tepat, sayang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('df1e3f93-7f47-4e5d-a657-ef3090d2bc58', 'vocabulary', '正す', '正す', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kata ini terdiri dari kanji dengan beberapa hiragana yang dilampirkan, diakhiri dengan bunyi う. Artinya, kata tersebut merupakan kata kerja. Kanji itu sendiri artinya "benar", lalu apa bentuk kata kerjanya? Itu akan menjadi koreksi.', 'Kata ini terdiri dari kanji dengan beberapa hiragana yang dilampirkan, diakhiri dengan bunyi う. Artinya, kata tersebut merupakan kata kerja. Kanji itu sendiri artinya "benar", lalu apa bentuk kata kerjanya? Itu akan menjadi koreksi.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
