INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('df1e3f93-7f47-4e5d-a657-ef3090d2bc58', 'しせいを正しなさい。', 'Perbaiki postur Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('df1e3f93-7f47-4e5d-a657-ef3090d2bc58', '王子はまちがいを正されてプライドがきずついた。', 'Kesalahan sang pangeran telah diperbaiki dan harga dirinya terluka.') ON CONFLICT DO NOTHING;
