INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6e05c9f9-2f0d-48f1-afdd-78e87c97eefa', 'はなこさんの目はいいですか？ ', 'Apakah Hanako memiliki mata yang bagus?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6e05c9f9-2f0d-48f1-afdd-78e87c97eefa', 'アメリカには目が三つある人々がすんでいる山があって、そこではまいとし二月八日におまつりがある。', 'Di Amerika, ada sebuah gunung yang dihuni oleh orang-orang bermata tiga dan mereka mengadakan festival pada tanggal 8 Februari setiap tahunnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6e05c9f9-2f0d-48f1-afdd-78e87c97eefa', 'うつくしいあおい目のおとこが大すき！', 'Saya suka pria dengan mata biru yang indah!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('61ca5759-bfc5-4c0e-88cb-e69cdcf9891a', 'vocabulary', '立つ', '立つ', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri artinya "berdiri", lalu apa versi kata kerjanya? Itu untuk berdiri.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri artinya "berdiri", lalu apa versi kata kerjanya? Itu untuk berdiri.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
