INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('61ca5759-bfc5-4c0e-88cb-e69cdcf9891a', 'あそこに立っているのは、ぼくのあにです。', 'Orang yang berdiri di sana adalah saudaraku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('61ca5759-bfc5-4c0e-88cb-e69cdcf9891a', 'その石の上に立ってください。', 'Silakan berdiri di atas batu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('61ca5759-bfc5-4c0e-88cb-e69cdcf9891a', 'あそこに立っているのが、あなたのみらいの子どもです。', 'Orang yang berdiri di sana adalah anak masa depanmu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2b2fcd77-056b-4a29-bba8-5934da191c11', 'vocabulary', '立てる', '立てる', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti “berdiri” dan ini berarti berdiri sesuatu. Bisa juga berarti membuat sesuatu, baik secara fisik, seperti mengeluarkan suara, maupun secara mental, seperti membuat rencana. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2b2fcd77-056b-4a29-bba8-5934da191c11', 'Untuk Mempertahankan Sesuatu', true) ON CONFLICT DO NOTHING;
