INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2b2fcd77-056b-4a29-bba8-5934da191c11', 'ロウソクは、なん本立てますか？ ', 'Berapa banyak lilin yang akan kamu padamkan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2b2fcd77-056b-4a29-bba8-5934da191c11', 'このしゃしん立てを立てるためのスタンドをさがしています。', 'Saya sedang mencari kuda-kuda untuk memasang bingkai foto ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2b2fcd77-056b-4a29-bba8-5934da191c11', 'ぼくのつくえにえんぴつを立ててくれませんか？', 'Bisakah Anda menaruh beberapa pensil di meja saya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('eebb8345-8b06-44ed-85f2-1dc822e4cfbe', 'vocabulary', '元', '元', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Jika digunakan sebagai awalan, kata ini memiliki arti yang terkait dengan mantan atau mantan.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Jika digunakan sebagai awalan, kata ini memiliki arti yang terkait dengan mantan atau mantan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
