INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ba65942b-d55f-4398-94b7-b57ce8811391', 'vocabulary', '大切', '大切', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Pikirkan kembali masa lalu. Dulu ketika keputusan dibuat dengan pedang. Pemotongan besar-besaran akan menjadi hal yang penting. Bayangkan saja sepasang samurai bersiap-siap, lalu menyerbu, lalu membuat satu tebasan besar. Itu adalah hal terpenting yang akan mereka lakukan dalam hidup mereka (jika mereka masih hidup!).', 'Pikirkan kembali masa lalu. Dulu ketika keputusan dibuat dengan pedang. Pemotongan besar-besaran akan menjadi hal yang penting. Bayangkan saja sepasang samurai bersiap-siap, lalu menyerbu, lalu membuat satu tebasan besar. Itu adalah hal terpenting yang akan mereka lakukan dalam hidup mereka (jika mereka masih hidup!).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
