INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d05b5c11-3541-48cf-bae9-64d9ec3fa085', 'ひゃくさいまで生きる人は少ない。', 'Hanya sedikit orang yang hidup sampai usia 100 tahun.') ON CONFLICT DO NOTHING;
