INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('220e17cd-1c0b-4cc6-ab2f-a19f6ed24af9', 'あかしんごうで、くるまは止まりました。', 'Mobil berhenti di sinyal merah.') ON CONFLICT DO NOTHING;
