INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('021346c8-94de-4a4f-839e-d941a551bd4e', 'おんがくを止めてください。', 'Tolong hentikan musiknya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('021346c8-94de-4a4f-839e-d941a551bd4e', '三びょうかんいきを止めてください。', 'Harap tahan napas selama 3 detik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('021346c8-94de-4a4f-839e-d941a551bd4e', 'かれがはしりさるのを止めるひつようがある。', 'Kita harus menghentikannya agar tidak melarikan diri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fa5b9f86-650f-4848-bf1b-4b9e8752a798', 'vocabulary', '中止', '中止', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Ketika ada sesuatu di tengah-tengah suatu tindakan tetapi dihentikan, ini berarti tindakan tersebut ditangguhkan. Bayangkan Anda membeku saat Anda berlari. Ini seperti itu.', 'Ketika ada sesuatu di tengah-tengah suatu tindakan tetapi dihentikan, ini berarti tindakan tersebut ditangguhkan. Bayangkan Anda membeku saat Anda berlari. Ini seperti itu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
