INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa5b9f86-650f-4848-bf1b-4b9e8752a798', 'やきゅうのしあいは、あめで中止になりました。', 'Pertandingan bisbol dibatalkan karena hujan.') ON CONFLICT DO NOTHING;
