INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6dbd3c77-8d1f-4d87-9851-6446cf3ff071', 'たんじょう日にはでんたくが十台ほしい。', 'Saya ingin sepuluh kalkulator untuk ulang tahun saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('60528dc7-429c-4966-ae26-82376bf6edee', 'vocabulary', '用いる', '用いる', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri berarti tugas atau kegunaan. Anda dapat menganggap kata kerja ini sebagai cara yang lebih formal untuk mengatakan menggunakan, yaitu memanfaatkan.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri berarti tugas atau kegunaan. Anda dapat menganggap kata kerja ini sebagai cara yang lebih formal untuk mengatakan menggunakan, yaitu memanfaatkan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
