INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('60528dc7-429c-4966-ae26-82376bf6edee', 'トーフグににたなまえを用いるものがいます。', 'Ada orang yang menggunakan nama mirip Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('60528dc7-429c-4966-ae26-82376bf6edee', '北ちょうせんは、かくへいきをおどしに用いる。', 'Korea Utara menggunakan senjata nuklir untuk mengancam negara lain.') ON CONFLICT DO NOTHING;
