INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4290cfdb-35ca-44f5-b1c1-47f98b0d600c', 'パソコンのスリープと休止じょうたいのちがいをおしえてください。', 'Bisakah Anda memberi tahu saya perbedaan antara mode tidur dan mode hibernasi di komputer?') ON CONFLICT DO NOTHING;
