INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a9758f22-c611-44d8-b65b-ac39327eab3c', 'お父さんは、元気ですか。', 'Bagaimana kabar ayahmu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a9758f22-c611-44d8-b65b-ac39327eab3c', 'かなちゃんは、元気いっぱいですね。', 'Kana penuh energi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a9758f22-c611-44d8-b65b-ac39327eab3c', '彼は元気そうに見えたが、実はひどい下りだったらしい。', 'Dia kelihatannya baik-baik saja tetapi tampaknya dia menderita diare yang parah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8d1fef41-3af1-49c5-994a-33c98e5554fa', 'vocabulary', '見方', '見方', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Cara Anda melihat adalah cara melihat sesuatu. Ini seperti ketika seseorang mempunyai opini bodoh dan kamu berkata "oh, oke, jadi itu salah satu cara untuk melihatnya..."', 'Cara Anda melihat adalah cara melihat sesuatu. Ini seperti ketika seseorang mempunyai opini bodoh dan kamu berkata "oh, oke, jadi itu salah satu cara untuk melihatnya..."') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
