INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8d1fef41-3af1-49c5-994a-33c98e5554fa', 'このひょうの見方が分かりません。', 'Saya tidak tahu cara melihat grafik ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8d1fef41-3af1-49c5-994a-33c98e5554fa', 'いろんな見方やとらえ方があります。', 'Ada berbagai cara untuk melihat dan memahami.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8d1fef41-3af1-49c5-994a-33c98e5554fa', '別の見方をすれば、トーフグは河豚味の豆腐だと考えることもできる。', 'Jika dilihat dari sudut pandang berbeda, kita bisa menganggap Tofugu adalah tahu yang rasanya fugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7f934a69-935a-45e5-9d8c-10333d720118', 'vocabulary', '世', '世', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
