INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7f934a69-935a-45e5-9d8c-10333d720118', 'このアプリは、まだ世に出ていません。', 'Aplikasi ini masih belum terkenal di dunia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7f934a69-935a-45e5-9d8c-10333d720118', 'まったく世も末だね。', 'Dunia benar-benar akan segera berakhir.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7f934a69-935a-45e5-9d8c-10333d720118', '暗殺者は別にして、スズメ蜂ほど怖いものはこの世の中にない。', 'Selain pembunuh, tidak ada yang lebih menakutkan di dunia ini selain tawon.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ad058e9e-ef5e-432a-a39d-8fdfbcc4fa52', 'vocabulary', '二世', '二世', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Generasi kedua adalah generasi kedua.', 'Generasi kedua adalah generasi kedua.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
