INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a8e46ef1-886a-4536-b007-232680859d7e', 'vocabulary', '一代', '一代', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kata ini memiliki kanji untuk satu dan titik. Anda hanya memiliki satu periode untuk hidup, jadi ini adalah satu-satunya masa hidup yang Anda dapatkan. Kecuali jika Anda dilahirkan kembali, tapi itu mungkin terjadi di zaman berikutnya, bukan di zaman ini. Jadi satu seumur hidup untukmu!', 'Kata ini memiliki kanji untuk satu dan titik. Anda hanya memiliki satu periode untuk hidup, jadi ini adalah satu-satunya masa hidup yang Anda dapatkan. Kecuali jika Anda dilahirkan kembali, tapi itu mungkin terjadi di zaman berikutnya, bukan di zaman ini. Jadi satu seumur hidup untukmu!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
