INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a9920e62-c377-4300-8bf6-39797038d097', 'vocabulary', '不正', '不正', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Ketika Anda memiliki sesuatu yang tidak benar, Anda tidak memiliki keadilan. Faktanya, Anda mengalami ketidakadilan. Bayangkan saja diri Anda berada dalam situasi yang tidak adil, dan pikirkan betapa tidak benarnya situasi tersebut. Itu mungkin juga tidak jujur ​​dan tidak sah.', 'Ketika Anda memiliki sesuatu yang tidak benar, Anda tidak memiliki keadilan. Faktanya, Anda mengalami ketidakadilan. Bayangkan saja diri Anda berada dalam situasi yang tidak adil, dan pikirkan betapa tidak benarnya situasi tersebut. Itu mungkin juga tidak jujur ​​dan tidak sah.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
