INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fcd22869-0520-4652-a5b8-92cfa213e9ea', '2016年4月から日本でスタートした、電力自由化についてくわしく教えてください。', 'Bisakah kamu ceritakan semua yang kamu ketahui tentang Liberalisasi Listrik yang dimulai di Jepang pada bulan April 2016.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fcd22869-0520-4652-a5b8-92cfa213e9ea', 'あの電力会社には電気代をはらいたくないよ。', 'Saya tidak ingin membayar tagihan kepada perusahaan listrik itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fcd22869-0520-4652-a5b8-92cfa213e9ea', '電力が約三時間で復旧したので、私は面接の前に電動バリカンで頭を刈って整えることができました。', 'Listrik pulih sekitar tiga jam dan saya dapat memperbaiki rambut saya dengan gunting rambut listrik sebelum wawancara.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('838faea9-7545-4b76-8896-fceaa4c5b42b', 'vocabulary', '主語', '主語', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Hal utama yang Anda bicarakan dalam bahasa Anda menjadi subjek kalimat.', 'Hal utama yang Anda bicarakan dalam bahasa Anda menjadi subjek kalimat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
