INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('838faea9-7545-4b76-8896-fceaa4c5b42b', '主語をハッキリさせてくれないかな。', 'Bisakah Anda memperjelas topiknya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('838faea9-7545-4b76-8896-fceaa4c5b42b', 'この主語を明かくにする新サービスは、本当に役に立つ。', 'Layanan baru yang memperjelas subjek ini sangat berguna.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('838faea9-7545-4b76-8896-fceaa4c5b42b', '日本語は、主語ー目的語ー動詞の言語ですが、英語は主語ー動詞ー目的語の言語です。', 'Bahasa Jepang adalah bahasa subjek-objek-kata kerja sedangkan bahasa Inggris adalah bahasa subjek-kata kerja-objek.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('91ab7580-beac-4333-9119-f4e58429ee99', 'vocabulary', '読み方', '読み方', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Anda tahu bahwa ini ada hubungannya dengan membaca dan Anda tahu bahwa 方 berarti cara atau metode. Jadi, ketika Anda memikirkan "cara membaca", Anda dapat memikirkan beberapa kata lain yang lebih baik, seperti membaca (alias membaca suatu kata) atau pengucapan. Kapan pun Anda ingin mengetahui bunyi sesuatu, inilah yang akan Anda minta.', 'Anda tahu bahwa ini ada hubungannya dengan membaca dan Anda tahu bahwa 方 berarti cara atau metode. Jadi, ketika Anda memikirkan "cara membaca", Anda dapat memikirkan beberapa kata lain yang lebih baik, seperti membaca (alias membaca suatu kata) atau pengucapan. Kapan pun Anda ingin mengetahui bunyi sesuatu, inilah yang akan Anda minta.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
