INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5391c288-647d-4686-af3b-5dd3de50ae67', '白い子牛をかっているんです。', 'Kami memiliki anak sapi putih.') ON CONFLICT DO NOTHING;
