INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('66c8800c-20f2-458f-8d58-4953b682350f', 'vocabulary', '切手', '切手', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Untuk mengingat arti kata ini, coba pikirkan bagaimana di masa lalu, sebelum ditemukan perforasi, orang harus memotong prangko dengan tangan. Butuh waktu lama, terutama jika Anda memiliki banyak teman yang bisa Anda kirimi surat. Bersyukurlah bahwa perforasi diciptakan untuk menghemat waktu Anda saat memotongnya.', 'Untuk mengingat arti kata ini, coba pikirkan bagaimana di masa lalu, sebelum ditemukan perforasi, orang harus memotong prangko dengan tangan. Butuh waktu lama, terutama jika Anda memiliki banyak teman yang bisa Anda kirimi surat. Bersyukurlah bahwa perforasi diciptakan untuk menghemat waktu Anda saat memotongnya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
