INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('66c8800c-20f2-458f-8d58-4953b682350f', 'それから、ゆうびんきょくへいって、切手をかいます。', 'Lalu saya akan pergi ke kantor pos dan membeli prangko.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('66c8800c-20f2-458f-8d58-4953b682350f', 'あの外人さんは切手を一万まいもかっていったよ。', 'Orang asing itu membeli 10.000 prangko.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('66c8800c-20f2-458f-8d58-4953b682350f', '彼女を失ってから、切手集めへの興味も失ってしまった。', 'Sejak saya kehilangan dia, saya kehilangan minat dalam mengoleksi prangko.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e46f1cc1-ae15-459d-944c-2090f063b2a3', 'vocabulary', '南口', '南口', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Mulut Selatan sebenarnya bukanlah mulut yang Anda temukan di kutub selatan atau apa pun, melainkan pintu masuk atau keluar. Ini seperti bagaimana 入り口 berarti pintu masuk (口 melambangkan pintu). Anda akan sering melihat kata ini di tempat-tempat seperti stasiun kereta atau bandara. Artinya pintu keluar Selatan dan pintu masuk Selatan.', 'Mulut Selatan sebenarnya bukanlah mulut yang Anda temukan di kutub selatan atau apa pun, melainkan pintu masuk atau keluar. Ini seperti bagaimana 入り口 berarti pintu masuk (口 melambangkan pintu). Anda akan sering melihat kata ini di tempat-tempat seperti stasiun kereta atau bandara. Artinya pintu keluar Selatan dan pintu masuk Selatan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
