INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e46f1cc1-ae15-459d-944c-2090f063b2a3', 'そこに行くなら、南口から出るのが一番近いです。', 'Jika Anda menuju ke sana, berangkat dari pintu keluar selatan adalah yang tercepat.') ON CONFLICT DO NOTHING;
