INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e46f1cc1-ae15-459d-944c-2090f063b2a3', '新宿南口でナンパされた。', 'Saya ditabrak di pintu keluar selatan stasiun Shinjuku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('11f5213f-e213-46a0-920f-2e5d9f9d3a40', 'vocabulary', '世の中', '世の中', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Dunia tengah adalah masyarakat. Itu yang menyatukan segalanya, bagi kita manusia. Anda juga bisa menyebutnya dunia.', 'Dunia tengah adalah masyarakat. Itu yang menyatukan segalanya, bagi kita manusia. Anda juga bisa menyebutnya dunia.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
