INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('11f5213f-e213-46a0-920f-2e5d9f9d3a40', 'よのなか', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('11f5213f-e213-46a0-920f-2e5d9f9d3a40', 'この世の中には、色んな人がいます。', 'Ada banyak tipe orang di dunia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('11f5213f-e213-46a0-920f-2e5d9f9d3a40', '世の中には、しんじつを知らない方がいいことだってあるんだよ。', 'Dalam masyarakat ini, tidak mengetahui kebenaran terkadang lebih baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('11f5213f-e213-46a0-920f-2e5d9f9d3a40', '我々は、警察よりも先にピザが家に到着するような素晴らしい世の中に住んでいる。', 'Kita hidup dalam masyarakat yang hebat di mana pizza sampai ke rumah Anda sebelum polisi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f1d58a4e-3992-4efc-8daa-263e75ec3f5a', 'vocabulary', '代わり', '代わり', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Anda pernah melihat bahwa 代わる berarti "menggantikan" atau "menggantikan". Ini adalah versi kata benda itu (tidak ada bunyi う di akhir). Jadi, apa versi kata benda dari kata kerja tersebut? Itu akan menjadi pengganti atau penggantian.', 'Anda pernah melihat bahwa 代わる berarti "menggantikan" atau "menggantikan". Ini adalah versi kata benda itu (tidak ada bunyi う di akhir). Jadi, apa versi kata benda dari kata kerja tersebut? Itu akan menjadi pengganti atau penggantian.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
