INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f1d58a4e-3992-4efc-8daa-263e75ec3f5a', 'かわり', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1d58a4e-3992-4efc-8daa-263e75ec3f5a', '代わりの先生をさがしています。', 'Kami sedang mencari guru pengganti.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1d58a4e-3992-4efc-8daa-263e75ec3f5a', 'この世のどこにも、かれの代わりはいないんです。', 'Tidak ada penggantinya di manapun di dunia ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1d58a4e-3992-4efc-8daa-263e75ec3f5a', '日本語を教わる代わりに、英語を教えることができますよ。', 'Saya bisa mengajari Anda bahasa Inggris dan sebagai gantinya Anda bisa mengajari saya bahasa Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('be46de7a-f612-450d-84b5-f252dcf5249a', 'vocabulary', '代える', '代える', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Anda tahu kanjinya adalah pengganti, dan Anda tahu ini adalah kata kerja. Ada yang serupa lainnya, tapi yang ini berarti mengganti sesuatu. Untuk mengingat bahwa kata khusus ini berarti "mengganti sesuatu" fokuslah pada え. Anda memiliki sebutir telur di tangan yang menurut Anda tidak ada gunanya (warnanya hitam dan berjamur). Jadi, Anda menggantinya dengan telur lain (atau menggantinya dengan telur lain, atau menukarnya dengan telur lain, dan seterusnya).
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('be46de7a-f612-450d-84b5-f252dcf5249a', 'Untuk Mengganti Sesuatu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('be46de7a-f612-450d-84b5-f252dcf5249a', 'To Substitute Something', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('be46de7a-f612-450d-84b5-f252dcf5249a', 'To Exchange Something', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('be46de7a-f612-450d-84b5-f252dcf5249a', 'かえる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('be46de7a-f612-450d-84b5-f252dcf5249a', 'かんとくは、ピッチャーを代えるだろう。', 'Menurut saya, pelatih sedang mengganti pelemparnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('be46de7a-f612-450d-84b5-f252dcf5249a', 'ふだんは、ヨーグルトをサワークリームに代えてつかっています。', 'Saya biasanya mengganti yogurt dengan krim asam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('be46de7a-f612-450d-84b5-f252dcf5249a', 'この指輪をお金に代えることはできません。', 'Saya tidak bisa menukar cincin ini dengan uang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1055c12b-223c-47c0-b98a-fea7b377b758', 'vocabulary', '不人気', '不人気', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Anda sudah tahu 人気 yang artinya "populer". Dan Anda juga tahu bahwa 不 berarti "tidak". Lalu apa yang Anda dapatkan jika menggabungkan keduanya? Sesuatu yang tidak populer atau tidak populer.', 'Anda sudah tahu 人気 yang artinya "populer". Dan Anda juga tahu bahwa 不 berarti "tidak". Lalu apa yang Anda dapatkan jika menggabungkan keduanya? Sesuatu yang tidak populer atau tidak populer.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1055c12b-223c-47c0-b98a-fea7b377b758', 'Tidak populer', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1055c12b-223c-47c0-b98a-fea7b377b758', 'Not Popular', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1055c12b-223c-47c0-b98a-fea7b377b758', 'ふにんき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1055c12b-223c-47c0-b98a-fea7b377b758', '今年、もっとも不人気だったアニメは何だと思いますか。', 'Menurutmu anime apa yang paling tidak populer tahun ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1055c12b-223c-47c0-b98a-fea7b377b758', 'コウイチたいマイケルのすもうのし合は、Youtubeで見るとはく力に欠けるので不人気です。', 'Pertandingan sumo Koichi vs Michael kurang populer karena kurang intensitasnya jika ditonton di YouTube.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1055c12b-223c-47c0-b98a-fea7b377b758', '「お前の母ちゃんに言ってやる」が口癖だったため、彼はクラスメートに不人気だった。', 'Dia tidak populer di kalangan teman-teman sekelasnya karena kalimat favoritnya adalah, "Aku akan memberitahu ibumu."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ceb89c19-ef90-49ed-9621-e07d3349d183', 'vocabulary', '東口', '東口', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Ingat bagaimana 入り口 berarti masuk dan 出口 berarti keluar? Ini hanyalah bagian 口 yang memiliki petunjuk arahnya. Artinya bisa menjadi pintu masuk atau keluar. Jadi bila ada Timur di sana, kata ini bisa berarti pintu keluar Timur dan pintu masuk Timur. Ini adalah kata yang bagus untuk diketahui jika Anda ingin mengetahui sisi stasiun kereta mana yang harus Anda tinggalkan untuk pergi ke suatu tempat atau bertemu seseorang!', 'Ingat bagaimana 入り口 berarti masuk dan 出口 berarti keluar? Ini hanyalah bagian 口 yang memiliki petunjuk arahnya. Artinya bisa menjadi pintu masuk atau keluar. Jadi bila ada Timur di sana, kata ini bisa berarti pintu keluar Timur dan pintu masuk Timur. Ini adalah kata yang bagus untuk diketahui jika Anda ingin mengetahui sisi stasiun kereta mana yang harus Anda tinggalkan untuk pergi ke suatu tempat atau bertemu seseorang!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ceb89c19-ef90-49ed-9621-e07d3349d183', 'Pintu Keluar Timur', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ceb89c19-ef90-49ed-9621-e07d3349d183', 'East Entrance', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ceb89c19-ef90-49ed-9621-e07d3349d183', 'Eastern Exit', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ceb89c19-ef90-49ed-9621-e07d3349d183', 'Eastern Entrance', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ceb89c19-ef90-49ed-9621-e07d3349d183', 'East Gate', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ceb89c19-ef90-49ed-9621-e07d3349d183', 'ひがしぐち', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ceb89c19-ef90-49ed-9621-e07d3349d183', 'えきの東口で大道げいをしている人がいたよ。', 'Ada seseorang yang sedang melakukan pertunjukan jalanan di pintu keluar timur stasiun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ceb89c19-ef90-49ed-9621-e07d3349d183', '東口でとった写しん、たぶん手ブレしたみたいで、ちょっとブレちゃってる。', 'Foto yang diambil di gerbang timur agak buram, mungkin karena kamera bergetar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ceb89c19-ef90-49ed-9621-e07d3349d183', '緊急の際には、このビルの東口から避難してください。そこでは、コーヒーとドーナツが支給される予定です。', 'Dalam keadaan darurat, harap evakuasi bangunan melalui pintu keluar timur. Akan ada kopi dan donat menunggu Anda di sana.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a80277d7-f014-4843-ac6a-c84f9a971f45', 'vocabulary', '話し方', '話し方', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Cara berbicara adalah cara Anda berbicara (atau bisa juga gaya berbicara Anda). Beginilah cara seseorang berbicara. Beberapa orang punya gaya bicara yang menarik.', 'Cara berbicara adalah cara Anda berbicara (atau bisa juga gaya berbicara Anda). Beginilah cara seseorang berbicara. Beberapa orang punya gaya bicara yang menarik.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
