INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a80277d7-f014-4843-ac6a-c84f9a971f45', 'はなしかた', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a80277d7-f014-4843-ac6a-c84f9a971f45', '話し方が本当にイライラするのよね。', 'Cara dia berbicara membuatku sangat kesal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a80277d7-f014-4843-ac6a-c84f9a971f45', 'コウイチの話し方って、かなりしぶいよね。', 'Gaya bicara Koichi sangat berbudaya ya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a80277d7-f014-4843-ac6a-c84f9a971f45', 'うわぁ！君の話し方、まるで母国語が日本語の人みたいだね。', 'Wow! Cara Anda berbicara terdengar seperti orang Jepang asli.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9e2fe102-763f-4dd4-b8f1-59d5acdd413f', 'vocabulary', '可分', '可分-4079', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Jika sesuatu dapat dipisahkan, maka sesuatu itu dapat dibagi. Bayangkan saja memisahkan sesuatu menjadi beberapa bagian. Itu mungkin. Jadi kalau bisa, itu habis dibagi. Sekarang pikirkan sesuatu yang bukan apa-apa (yaitu "tidak ada permen batangan"). Itu tidak mungkin dipisahkan menjadi beberapa bagian. Itu tidak dapat dibagi.', 'Jika sesuatu dapat dipisahkan, maka sesuatu itu dapat dibagi. Bayangkan saja memisahkan sesuatu menjadi beberapa bagian. Itu mungkin. Jadi kalau bisa, itu habis dibagi. Sekarang pikirkan sesuatu yang bukan apa-apa (yaitu "tidak ada permen batangan"). Itu tidak mungkin dipisahkan menjadi beberapa bagian. Itu tidak dapat dibagi.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9e2fe102-763f-4dd4-b8f1-59d5acdd413f', 'Dapat dibagi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9e2fe102-763f-4dd4-b8f1-59d5acdd413f', 'Separable', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9e2fe102-763f-4dd4-b8f1-59d5acdd413f', 'かぶん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9e2fe102-763f-4dd4-b8f1-59d5acdd413f', '今日のトーフグポッドキャストのテーマは、生と死の不可分性です。', 'Tema podcast Tofugu hari ini adalah tidak terpisahkannya hidup dan mati.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9e2fe102-763f-4dd4-b8f1-59d5acdd413f', '英文けい約書には、一ぱんじょうこうの一つに、可分性というじょうこうがよくあります。', 'Kontrak Inggris sering kali memiliki klausul keterpisahan sebagai salah satu ketentuan umum.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9e2fe102-763f-4dd4-b8f1-59d5acdd413f', '預貯金などの可分債権は、原則として遺産分割の対象にはなりません。', 'Sebagai aturan umum, klaim yang dapat dibagi, seperti rekening tabungan, tidak menjadi sasaran pembagian harta warisan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9ca1db73-b481-4d7c-a119-05da1fc34997', 'vocabulary', '書き方', '書き方', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Ini adalah cara penulisannya (seperti 見方 cara melihat). Namun, cara yang lebih baik untuk mengatakan hal ini adalah dengan menyebutnya sebagai tulisan tangan. Bagaimana kabarmu? Milik saya sangat buruk.', 'Ini adalah cara penulisannya (seperti 見方 cara melihat). Namun, cara yang lebih baik untuk mengatakan hal ini adalah dengan menyebutnya sebagai tulisan tangan. Bagaimana kabarmu? Milik saya sangat buruk.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9ca1db73-b481-4d7c-a119-05da1fc34997', 'Tulisan tangan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9ca1db73-b481-4d7c-a119-05da1fc34997', 'Way Of Writing', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9ca1db73-b481-4d7c-a119-05da1fc34997', 'Manner Of Writing', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9ca1db73-b481-4d7c-a119-05da1fc34997', 'かきかた', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9ca1db73-b481-4d7c-a119-05da1fc34997', 'この漢字の書き方が思い出せない。', 'Saya tidak ingat bagaimana menulis kanji ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9ca1db73-b481-4d7c-a119-05da1fc34997', 'トーフグにはどうして書き方を教えるアプリが無いんですか？', 'Mengapa Tofugu tidak memiliki aplikasi untuk mengajarkan cara menulis?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9ca1db73-b481-4d7c-a119-05da1fc34997', '平仮名の綺麗な書き方を勉強することには、心底飽き飽きしてるんだよね！', 'Saya bosan dengan mempelajari tulisan tangan hiragana.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('15fab8f7-3fa7-4d2b-bd10-99eb31a5979d', 'vocabulary', '不可分', '不可分', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Jika sesuatu tidak dapat dipisahkan menjadi beberapa bagian, maka sesuatu itu tidak dapat dibagi lagi.', 'Jika sesuatu tidak dapat dipisahkan menjadi beberapa bagian, maka sesuatu itu tidak dapat dibagi lagi.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('15fab8f7-3fa7-4d2b-bd10-99eb31a5979d', 'Tak terpisahkan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('15fab8f7-3fa7-4d2b-bd10-99eb31a5979d', 'Inseparable', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('15fab8f7-3fa7-4d2b-bd10-99eb31a5979d', 'ふかぶん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('15fab8f7-3fa7-4d2b-bd10-99eb31a5979d', 'ビエトとコウイチは、不可分の関係にあるんですよ。', 'Viet dan Koichi tidak dapat dipisahkan satu sama lain.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('15fab8f7-3fa7-4d2b-bd10-99eb31a5979d', 'けい約では、それは不可分なさいむだったはずですよ。', 'Saya cukup yakin itu adalah kewajiban yang tidak dapat dipisahkan dalam kontrak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('15fab8f7-3fa7-4d2b-bd10-99eb31a5979d', 'ご存知のように、豆腐と河豚は不可分です。', 'Seperti yang kita ketahui bersama, Tahu dan Fugu tidak dapat dipisahkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('638b041b-47a7-4917-9f7f-ec91d67d5ea2', 'vocabulary', '時代', '時代', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Anda mempunyai suatu periode waktu dan itu disebut periode atau era! Sederhana!', 'Anda mempunyai suatu periode waktu dan itu disebut periode atau era! Sederhana!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
